public class InnerConnectionTypeBasicAuthenticationPropertiesFactory(Action<Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties>
{

    internal InnerConnectionTypeSecretConnectorPropertyFactory UsernameFactory { get; set; }

    internal InnerConnectionTypeSecretConnectorPropertyFactory PasswordFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties Create()
    {
        var basicAuthenticationPropertiesResult = CreateBasicAuthenticationProperties();
        factoryAction?.Invoke(basicAuthenticationPropertiesResult);

        return basicAuthenticationPropertiesResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties CreateBasicAuthenticationProperties()
    {
        var basicAuthenticationPropertiesResult = new Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties();

        return basicAuthenticationPropertiesResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.BasicAuthenticationProperties result)
    {
        base.CreateChildren(result);

        result.Username ??= UsernameFactory?.Build();
        result.Password ??= PasswordFactory?.Build();
    }

} // End Of Class

